import RadioGroup from "@marko-ui/shadcn/ui/radio-group/radio-group.marko";

static const ITEMS = [
  { value: "default", label: "Default" },
  { value: "comfortable", label: "Comfortable" },
  { value: "compact", label: "Compact" },
];

<RadioGroup items=ITEMS defaultValue="comfortable"/>

import RadioGroup from "@marko-ui/shadcn/ui/radio-group/radio-group.marko";
import FieldSet from "@marko-ui/shadcn/ui/field/field-set.marko";
import FieldLegend from "@marko-ui/shadcn/ui/field/field-legend.marko";
import FieldDescription from "@marko-ui/shadcn/ui/field/field-description.marko";

static const PLANS = [
  { value: "monthly", label: "Monthly ($9.99/month)" },
  { value: "yearly", label: "Yearly ($99.99/year)" },
  { value: "lifetime", label: "Lifetime ($299.99)" },
];

<FieldSet class="w-full max-w-xs">
  <FieldLegend variant="label">Subscription Plan</FieldLegend>
  <FieldDescription>Yearly and lifetime plans offer significant savings.</FieldDescription>
  <RadioGroup items=PLANS value="monthly" class="mt-3"/>
</FieldSet>

import RadioGroup from "@marko-ui/shadcn/ui/radio-group/radio-group.marko";

static const ITEMS = [
  { value: "card", label: "Card" },
  { value: "paypal", label: "PayPal" },
  { value: "apple-pay", label: "Apple Pay", disabled: true },
];

<RadioGroup items=ITEMS value="card"/>

import RadioGroup from "@marko-ui/shadcn/ui/radio-group/radio-group.marko";

static const ITEMS = [
  { value: "default", label: "Default" },
  { value: "comfortable", label: "Comfortable" },
  { value: "compact", label: "Compact" },
];

<RadioGroup items=ITEMS value="default" disabled/>

import RadioGroup from "@marko-ui/shadcn/ui/radio-group/radio-group.marko";

static const ITEMS = [
  { value: "default", label: "افتراضي" },
  { value: "comfortable", label: "مريح" },
  { value: "compact", label: "مضغوط" },
];

<RadioGroup items=ITEMS value="comfortable" dir="rtl" class="w-fit"/>
